-- Private historical economic audit continuations. No active collection authority.
CREATE TABLE app_collection_legacy_economics (
 id TEXT PRIMARY KEY,relation_audit_id TEXT NOT NULL UNIQUE REFERENCES app_collection_legacy_relations(id),operator TEXT NOT NULL,
 as_of_ms INTEGER NOT NULL CHECK(as_of_ms BETWEEN 0 AND 8640000000000000),
 stage_originals_json TEXT NOT NULL CHECK(json_valid(stage_originals_json) AND json_type(stage_originals_json)='array' AND json_array_length(stage_originals_json)<=32 AND length(CAST(stage_originals_json AS BLOB))<=16384),
 selection_digest TEXT NOT NULL CHECK(length(selection_digest)=64 AND selection_digest NOT GLOB '*[^0-9a-f]*'),
 state TEXT NOT NULL CHECK(state IN ('working','ready','held')),
 phase TEXT NOT NULL CHECK(phase IN ('stage','initialize','select','prepare','control','mint','membership','advance','closure','finish')),
 stage_index INTEGER NOT NULL CHECK(stage_index BETWEEN 0 AND 32),ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 1000),
 revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 9007199254740991),
 prefix_json TEXT CHECK(prefix_json IS NULL OR json_valid(prefix_json) AND length(CAST(prefix_json AS BLOB))<=8192),
 context_json TEXT CHECK(context_json IS NULL OR json_valid(context_json) AND length(CAST(context_json AS BLOB))<=32768),
 chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),
 result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json) AND length(CAST(result_json AS BLOB))<=16384),
 last_nonce TEXT NOT NULL,reason TEXT,created_ms INTEGER NOT NULL,updated_ms INTEGER NOT NULL,
 CHECK(state<>'ready' OR result_json IS NOT NULL AND context_json IS NULL AND phase='finish'),
 CHECK(state='ready' OR result_json IS NULL),
 CHECK((state='held' AND reason IS NOT NULL) OR (state<>'held' AND reason IS NULL))
) STRICT;
CREATE TABLE app_collection_legacy_economic_stages (
 audit_id TEXT NOT NULL REFERENCES app_collection_legacy_economics(id),stage_index INTEGER NOT NULL CHECK(stage_index BETWEEN 0 AND 31),stage_id TEXT NOT NULL,
 original_identity_json TEXT NOT NULL CHECK(json_valid(original_identity_json) AND length(CAST(original_identity_json AS BLOB))<=1024),
 proof_json TEXT NOT NULL CHECK(json_valid(proof_json) AND length(CAST(proof_json AS BLOB))<=8192),
 proof_digest TEXT NOT NULL CHECK(length(proof_digest)=64 AND proof_digest NOT GLOB '*[^0-9a-f]*'),
 prior_chain_digest TEXT NOT NULL CHECK(length(prior_chain_digest)=64 AND prior_chain_digest NOT GLOB '*[^0-9a-f]*'),
 chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),
 run_revision INTEGER NOT NULL CHECK(run_revision BETWEEN 1 AND 9007199254740991),PRIMARY KEY(audit_id,stage_index),UNIQUE(audit_id,stage_id)
) STRICT;
CREATE TABLE app_collection_legacy_economic_phases (
 audit_id TEXT NOT NULL REFERENCES app_collection_legacy_economics(id),ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 1000),
 phase TEXT NOT NULL CHECK(phase IN ('select','prepare','control','mint','membership','advance','closure')),
 body_json TEXT NOT NULL CHECK(json_valid(body_json) AND length(CAST(body_json AS BLOB))<=32768),
 proof_digest TEXT NOT NULL CHECK(length(proof_digest)=64 AND proof_digest NOT GLOB '*[^0-9a-f]*'),
 prior_chain_digest TEXT NOT NULL CHECK(length(prior_chain_digest)=64 AND prior_chain_digest NOT GLOB '*[^0-9a-f]*'),
 chain_digest TEXT NOT NULL CHECK(length(chain_digest)=64 AND chain_digest NOT GLOB '*[^0-9a-f]*'),
 run_revision INTEGER NOT NULL CHECK(run_revision BETWEEN 1 AND 9007199254740991),PRIMARY KEY(audit_id,ordinal,phase)
) STRICT;
CREATE TRIGGER collection_legacy_economics_initial BEFORE INSERT ON app_collection_legacy_economics BEGIN
 SELECT RAISE(ABORT,'Economic audit begins with empty private progress') WHERE NEW.state<>'working' OR NEW.phase<>'stage' OR NEW.stage_index<>0 OR NEW.ordinal<>0 OR NEW.revision<>0 OR NEW.prefix_json IS NOT NULL OR NEW.context_json IS NOT NULL OR NEW.result_json IS NOT NULL OR NEW.chain_digest<>NEW.selection_digest;
 SELECT RAISE(ABORT,'Economic audit requires retained source relation') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_relations r JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id JOIN app_collection_source_seals s ON s.id=p.root_id WHERE r.id=NEW.relation_audit_id AND r.state='ready' AND p.state='fingerprints-ready' AND r.operator=NEW.operator AND p.operator=NEW.operator AND json_array_length(NEW.stage_originals_json)=s.stage_count);
END;
CREATE TRIGGER collection_legacy_economic_stage_insert BEFORE INSERT ON app_collection_legacy_economic_stages BEGIN
 SELECT RAISE(ABORT,'Stage proof must extend current private audit') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_economics e JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id WHERE e.id=NEW.audit_id AND e.state='working' AND e.phase='stage' AND e.stage_index=NEW.stage_index AND e.revision+1=NEW.run_revision AND e.chain_digest=NEW.prior_chain_digest AND json_extract(e.stage_originals_json,'$['||NEW.stage_index||']') IS NEW.original_identity_json AND json_extract(NEW.proof_json,'$.format') IS 'legacy-economic-stage-proof-v1' AND json_extract(NEW.proof_json,'$.value.stageAudit.kind') IS 'verified' AND json_extract(NEW.proof_json,'$.rootId') IS p.root_id AND json_extract(NEW.proof_json,'$.stageIndex') IS NEW.stage_index AND json_extract(NEW.proof_json,'$.value.stageAudit.stageId') IS NEW.stage_id AND json_extract(NEW.proof_json,'$.value.originalIdentity') IS NEW.original_identity_json AND json_extract(NEW.proof_json,'$.value.stageAudit.verification') IS 'publication-preimage-and-scalar-reducer-only' AND json_extract(NEW.proof_json,'$.value.stageAudit.executable') IS 0);
END;
CREATE TRIGGER collection_legacy_economic_phase_insert BEFORE INSERT ON app_collection_legacy_economic_phases BEGIN
 SELECT RAISE(ABORT,'Phase proof must extend current private audit') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_economics e JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id WHERE e.id=NEW.audit_id AND e.state='working' AND e.phase=NEW.phase AND e.ordinal=NEW.ordinal AND e.revision+1=NEW.run_revision AND e.chain_digest=NEW.prior_chain_digest AND json_extract(NEW.body_json,'$.format') IS 'legacy-economic-phase-proof-v1' AND (NEW.phase='select' OR json_type(NEW.body_json,'$.value') IS 'object') AND json_extract(NEW.body_json,'$.rootId') IS p.root_id AND json_extract(NEW.body_json,'$.ordinal') IS NEW.ordinal AND json_extract(NEW.body_json,'$.phase') IS NEW.phase AND json_type(NEW.body_json,'$.value') IS NOT NULL);
END;
CREATE TRIGGER collection_legacy_economic_closure_insert BEFORE INSERT ON app_collection_legacy_economic_phases WHEN NEW.phase='closure' BEGIN
 SELECT RAISE(ABORT,'Missing typed original operation closure') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_economics e JOIN app_collection_legacy_relations r ON r.id=e.relation_audit_id JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id JOIN app_collection_source_seals s ON s.id=p.root_id WHERE e.id=NEW.audit_id AND json_extract(NEW.body_json,'$.value.kind') IS 'verified' AND json_extract(NEW.body_json,'$.value.rootId') IS p.root_id AND json_extract(NEW.body_json,'$.value.sourcePin.inventoryId') IS p.inventory_id AND json_extract(NEW.body_json,'$.value.sourcePin.sourceRevision') IS CAST(p.source_revision AS TEXT) AND json_extract(NEW.body_json,'$.value.sourcePin.generation') IS json_extract(p.descriptor_json,'$.sourceGeneration') AND json_extract(NEW.body_json,'$.value.sourcePin.watermark') IS json_extract(p.descriptor_json,'$.sourceWatermark') AND json_type(NEW.body_json,'$.value.sourceDigest') IS 'text' AND length(json_extract(NEW.body_json,'$.value.sourceDigest'))=64 AND json_extract(NEW.body_json,'$.value.sourceDigest') NOT GLOB '*[^0-9a-f]*' AND json_extract(NEW.body_json,'$.value.counts.operationCount') IS s.admission_count AND json_extract(NEW.body_json,'$.value.counts.admissionCount') IS s.admission_count AND json_extract(NEW.body_json,'$.value.counts.distinctOperations') IS s.admission_count AND json_extract(NEW.body_json,'$.value.counts.distinctCommitments') IS s.admission_count AND json_type(NEW.body_json,'$.value.counts.proofs') IS 'integer' AND json_type(NEW.body_json,'$.value.counts.distinctProofs') IS 'integer' AND json_extract(NEW.body_json,'$.value.counts.proofs') IS json_extract(NEW.body_json,'$.value.counts.distinctProofs') AND json_extract(NEW.body_json,'$.value.counts.proofs') BETWEEN 0 AND s.admission_count AND json_extract(NEW.body_json,'$.value.counts.missingOperations') IS 0 AND json_extract(NEW.body_json,'$.value.sourceRelation') IS 0 AND json_extract(NEW.body_json,'$.value.economics') IS 0 AND json_extract(NEW.body_json,'$.value.adoption') IS 0);
END;
CREATE TRIGGER collection_legacy_economics_update BEFORE UPDATE ON app_collection_legacy_economics BEGIN
 SELECT RAISE(ABORT,'Retain immutable economic audit identity') WHERE NEW.id<>OLD.id OR NEW.relation_audit_id<>OLD.relation_audit_id OR NEW.operator<>OLD.operator OR NEW.as_of_ms<>OLD.as_of_ms OR NEW.stage_originals_json<>OLD.stage_originals_json OR NEW.selection_digest<>OLD.selection_digest OR NEW.created_ms<>OLD.created_ms OR OLD.state<>'working' OR NEW.revision<>OLD.revision+1 OR NEW.last_nonce=OLD.last_nonce OR NEW.updated_ms<OLD.updated_ms;
 SELECT RAISE(ABORT,'Economic readiness requires finish phase') WHERE NEW.state='ready' AND OLD.phase<>'finish';
 SELECT RAISE(ABORT,'Held economic audit retains exact prefix') WHERE NEW.state='held' AND (NEW.phase<>OLD.phase OR NEW.stage_index<>OLD.stage_index OR NEW.ordinal<>OLD.ordinal OR NEW.prefix_json IS NOT OLD.prefix_json OR NEW.context_json IS NOT OLD.context_json OR NEW.chain_digest<>OLD.chain_digest);
 SELECT RAISE(ABORT,'Invalid private economic phase transition') WHERE NEW.state<>'held' AND NOT (
  (OLD.phase='stage' AND NEW.phase IN ('stage','initialize') AND NEW.ordinal=OLD.ordinal AND NEW.stage_index IN (OLD.stage_index,OLD.stage_index+1) AND NEW.prefix_json IS OLD.prefix_json AND NEW.context_json IS OLD.context_json)
  OR (OLD.phase='initialize' AND NEW.phase IN ('select','closure') AND NEW.stage_index=OLD.stage_index AND NEW.ordinal=0 AND NEW.chain_digest=OLD.chain_digest AND json_extract(NEW.prefix_json,'$.ordinal') IS 0 AND NEW.context_json IS NULL)
  OR (OLD.phase IN ('select','prepare','control','mint','membership') AND NEW.phase=CASE OLD.phase WHEN 'select' THEN 'prepare' WHEN 'prepare' THEN 'control' WHEN 'control' THEN 'mint' WHEN 'mint' THEN 'membership' WHEN 'membership' THEN 'advance' END AND NEW.stage_index=OLD.stage_index AND NEW.ordinal=OLD.ordinal AND NEW.prefix_json IS OLD.prefix_json)
  OR (OLD.phase='advance' AND NEW.phase IN ('select','closure') AND NEW.stage_index=OLD.stage_index AND NEW.ordinal=OLD.ordinal+1 AND json_extract(NEW.prefix_json,'$.ordinal') IS NEW.ordinal AND NEW.context_json IS NULL)
  OR (OLD.phase='closure' AND NEW.phase='finish' AND NEW.stage_index=OLD.stage_index AND NEW.ordinal=OLD.ordinal AND NEW.prefix_json IS OLD.prefix_json AND json_extract(NEW.context_json,'$.closure.kind') IS 'verified')
  OR (OLD.phase='finish' AND NEW.phase='finish' AND NEW.state='ready' AND NEW.stage_index=OLD.stage_index AND NEW.ordinal=OLD.ordinal AND NEW.prefix_json IS OLD.prefix_json AND NEW.chain_digest=OLD.chain_digest AND NEW.context_json IS NULL)
 );
 SELECT RAISE(ABORT,'Economic phase must follow exact source counts') WHERE NEW.state<>'held' AND (
 (OLD.phase='stage' AND NEW.phase<>CASE WHEN NEW.stage_index=json_array_length(OLD.stage_originals_json) THEN 'initialize' ELSE 'stage' END)
 OR (OLD.phase IN ('initialize','advance') AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_relations r WHERE r.id=NEW.relation_audit_id AND NEW.ordinal<=json_extract(r.result_json,'$.admissionCount') AND NEW.phase=CASE WHEN NEW.ordinal=json_extract(r.result_json,'$.admissionCount') THEN 'closure' ELSE 'select' END)));
 SELECT RAISE(ABORT,'Missing exact stage proof effect') WHERE NEW.state<>'held' AND OLD.phase='stage' AND NEW.stage_index=OLD.stage_index+1 AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_stages s WHERE s.audit_id=OLD.id AND s.stage_index=OLD.stage_index AND s.run_revision=NEW.revision AND s.prior_chain_digest=OLD.chain_digest AND s.chain_digest=NEW.chain_digest);
 SELECT RAISE(ABORT,'Stage completion requires all retained proofs') WHERE NEW.state<>'held' AND OLD.phase='stage' AND (NEW.stage_index<>(SELECT COUNT(*) FROM app_collection_legacy_economic_stages WHERE audit_id=OLD.id) OR (NEW.stage_index=OLD.stage_index AND (NEW.phase<>'initialize' OR NEW.chain_digest<>OLD.chain_digest)) OR (NEW.phase='initialize' AND NEW.stage_index<>json_array_length(OLD.stage_originals_json)));
 SELECT RAISE(ABORT,'Missing exact phase proof effect') WHERE NEW.state<>'held' AND OLD.phase IN ('select','prepare','control','mint','membership','advance','closure') AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases a WHERE a.audit_id=OLD.id AND a.ordinal=OLD.ordinal AND a.phase=OLD.phase AND a.run_revision=NEW.revision AND a.prior_chain_digest=OLD.chain_digest AND a.chain_digest=NEW.chain_digest);
 SELECT RAISE(ABORT,'Selected original must equal immutable proof') WHERE NEW.state<>'held' AND OLD.phase='select' AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases a WHERE a.audit_id=OLD.id AND a.ordinal=OLD.ordinal AND a.phase='select' AND OLD.context_json IS NULL AND NEW.context_json IS json_object('selection',json_extract(a.body_json,'$.value')));
 SELECT RAISE(ABORT,'Context must retain prior facts and exact phase proof') WHERE NEW.state<>'held' AND OLD.phase IN ('prepare','control','mint','membership') AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases a WHERE a.audit_id=OLD.id AND a.ordinal=OLD.ordinal AND a.phase=OLD.phase AND json_type(OLD.context_json,'$.'||CASE OLD.phase WHEN 'prepare' THEN 'prepared' ELSE OLD.phase END) IS NULL AND json_type(NEW.context_json,'$.'||CASE OLD.phase WHEN 'prepare' THEN 'prepared' ELSE OLD.phase END) IS 'object' AND json_extract(NEW.context_json,'$.'||CASE OLD.phase WHEN 'prepare' THEN 'prepared' ELSE OLD.phase END) IS json_extract(a.body_json,'$.value') AND json_remove(NEW.context_json,'$.'||CASE OLD.phase WHEN 'prepare' THEN 'prepared' ELSE OLD.phase END) IS OLD.context_json);
 SELECT RAISE(ABORT,'Closure context must equal immutable proof') WHERE NEW.state<>'held' AND OLD.phase='closure' AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases a WHERE a.audit_id=OLD.id AND a.ordinal=OLD.ordinal AND a.phase='closure' AND OLD.context_json IS NULL AND NEW.context_json IS json_object('closure',json_extract(a.body_json,'$.value')));
 SELECT RAISE(ABORT,'Advance prefix must equal its immutable proof') WHERE NEW.state<>'held' AND OLD.phase='advance' AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_phases a WHERE a.audit_id=OLD.id AND a.ordinal=OLD.ordinal AND a.phase='advance' AND json_extract(a.body_json,'$.value.nextPrefix') IS NEW.prefix_json);
 SELECT RAISE(ABORT,'Missing complete typed economic prefix') WHERE NEW.prefix_json IS NOT NULL AND NOT EXISTS(SELECT 1 WHERE json_type(NEW.prefix_json) IS 'object' AND (SELECT COUNT(*) FROM json_each(NEW.prefix_json))=11 AND json_type(NEW.prefix_json,'$.rootId') IS 'text' AND length(json_extract(NEW.prefix_json,'$.rootId'))=64 AND json_type(NEW.prefix_json,'$.ordinal') IS 'integer' AND json_extract(NEW.prefix_json,'$.ordinal') BETWEEN 0 AND 1000 AND json_type(NEW.prefix_json,'$.pageIndex') IS 'integer' AND json_extract(NEW.prefix_json,'$.pageIndex') BETWEEN 0 AND 16 AND json_type(NEW.prefix_json,'$.entryIndex') IS 'integer' AND json_extract(NEW.prefix_json,'$.entryIndex') BETWEEN 0 AND 100 AND json_type(NEW.prefix_json,'$.fulfilled') IS 'integer' AND json_extract(NEW.prefix_json,'$.fulfilled') BETWEEN 0 AND 1000 AND json_type(NEW.prefix_json,'$.pending') IS 'integer' AND json_extract(NEW.prefix_json,'$.pending') BETWEEN 0 AND 1000 AND json_type(NEW.prefix_json,'$.paid') IS 'integer' AND json_extract(NEW.prefix_json,'$.paid') BETWEEN 0 AND 1000 AND json_type(NEW.prefix_json,'$.free') IS 'integer' AND json_extract(NEW.prefix_json,'$.free') BETWEEN 0 AND 1000 AND json_type(NEW.prefix_json,'$.founder') IS 'integer' AND json_extract(NEW.prefix_json,'$.founder') BETWEEN 0 AND 1000 AND json_type(NEW.prefix_json,'$.remaining') IS 'array' AND json_array_length(NEW.prefix_json,'$.remaining')=10 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.prefix_json,'$.remaining') q WHERE q.type<>'integer' OR q.value<0 OR q.value>json_extract('[489,256,128,64,32,16,8,4,2,1]','$['||q.key||']')) AND (SELECT SUM(value) FROM json_each(NEW.prefix_json,'$.remaining'))+json_extract(NEW.prefix_json,'$.fulfilled')=1000 AND json_extract(NEW.prefix_json,'$.fulfilled')+json_extract(NEW.prefix_json,'$.pending')=json_extract(NEW.prefix_json,'$.ordinal') AND json_extract(NEW.prefix_json,'$.paid')+json_extract(NEW.prefix_json,'$.free')+json_extract(NEW.prefix_json,'$.founder')=json_extract(NEW.prefix_json,'$.fulfilled') AND json_type(NEW.prefix_json,'$.stages') IS 'array' AND json_array_length(NEW.prefix_json,'$.stages')=json_array_length(NEW.stage_originals_json) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.prefix_json,'$.stages') q WHERE q.type<>'object' OR json_type(q.value,'$.id') IS NOT 'text' OR json_type(q.value,'$.type') IS NOT 'text' OR json_type(q.value,'$.admitted') IS NOT 'integer' OR json_extract(q.value,'$.admitted') NOT BETWEEN 0 AND 1000 OR json_type(q.value,'$.spentLamports') IS NOT 'text' OR NOT EXISTS(SELECT 1 FROM app_collection_legacy_economic_stages x WHERE x.audit_id=NEW.id AND x.stage_index=q.key AND x.stage_id=json_extract(q.value,'$.id'))) AND COALESCE((SELECT SUM(json_extract(value,'$.admitted')) FROM json_each(NEW.prefix_json,'$.stages')),0)=json_extract(NEW.prefix_json,'$.ordinal'));
 SELECT RAISE(ABORT,'Initial economic prefix requires zero counters') WHERE NEW.state<>'held' AND OLD.phase='initialize' AND (json_extract(NEW.prefix_json,'$.ordinal') IS NOT 0 OR json_extract(NEW.prefix_json,'$.pageIndex') IS NOT 0 OR json_extract(NEW.prefix_json,'$.entryIndex') IS NOT 0 OR json_extract(NEW.prefix_json,'$.fulfilled') IS NOT 0 OR json_extract(NEW.prefix_json,'$.pending') IS NOT 0 OR json_extract(NEW.prefix_json,'$.paid') IS NOT 0 OR json_extract(NEW.prefix_json,'$.free') IS NOT 0 OR json_extract(NEW.prefix_json,'$.founder') IS NOT 0 OR json_extract(NEW.prefix_json,'$.remaining') IS NOT '[489,256,128,64,32,16,8,4,2,1]' OR EXISTS(SELECT 1 FROM json_each(NEW.prefix_json,'$.stages') q WHERE json_extract(q.value,'$.spentLamports') IS NOT '0'));
 SELECT RAISE(ABORT,'Economic prefix root changed') WHERE NEW.prefix_json IS NOT NULL AND NOT EXISTS(SELECT 1 FROM app_collection_legacy_relations r JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id WHERE r.id=NEW.relation_audit_id AND json_extract(NEW.prefix_json,'$.rootId') IS p.root_id);
END;
CREATE TRIGGER collection_legacy_economics_ready BEFORE UPDATE ON app_collection_legacy_economics WHEN NEW.state='ready' BEGIN
 SELECT RAISE(ABORT,'Missing exact historical economic closure') WHERE NOT EXISTS(SELECT 1 FROM app_collection_legacy_relations r JOIN app_collection_legacy_audits p ON p.id=r.parent_audit_id JOIN app_collection_source_seals s ON s.id=p.root_id JOIN collect_inventories c ON c.id=p.inventory_id WHERE r.id=NEW.relation_audit_id AND r.state='ready' AND p.state='fingerprints-ready' AND r.operator=NEW.operator AND p.operator=NEW.operator AND NEW.stage_index=s.stage_count AND NEW.ordinal=s.admission_count AND (SELECT COUNT(*) FROM app_collection_legacy_economic_stages WHERE audit_id=NEW.id)=s.stage_count AND (SELECT COUNT(*) FROM app_collection_legacy_economic_phases WHERE audit_id=NEW.id AND phase='advance')=s.admission_count AND json_type(NEW.result_json,'$.counts') IS 'object' AND json_type(NEW.result_json,'$.stages') IS 'array' AND json_type(NEW.result_json,'$.remaining') IS 'array' AND json_extract(NEW.result_json,'$.kind') IS 'verified' AND json_extract(NEW.result_json,'$.rootId') IS p.root_id AND json_extract(NEW.result_json,'$.inventoryId') IS p.inventory_id AND json_extract(NEW.result_json,'$.admitted') IS s.admission_count AND json_extract(NEW.result_json,'$.fulfilled') IS json_extract(c.state,'$.fulfilled') AND json_extract(NEW.result_json,'$.fulfilled') IS json_extract(NEW.prefix_json,'$.fulfilled') AND json_extract(NEW.result_json,'$.remaining') IS json_extract(NEW.prefix_json,'$.remaining') AND json_extract(NEW.result_json,'$.remaining') IS json_extract(c.state,'$.remaining') AND json_extract(NEW.result_json,'$.verification') IS 'historical-admission-economics' AND json_extract(NEW.result_json,'$.source') IS 'local-reference-fixture' AND json_extract(NEW.result_json,'$.counts.paid') IS json_extract(NEW.prefix_json,'$.paid') AND json_extract(NEW.result_json,'$.counts.free') IS json_extract(NEW.prefix_json,'$.free') AND json_extract(NEW.result_json,'$.counts.founder') IS json_extract(NEW.prefix_json,'$.founder') AND json_extract(NEW.result_json,'$.counts.pending') IS json_extract(NEW.prefix_json,'$.pending') AND json_extract(NEW.result_json,'$.counts.unsold') IS 1000-s.admission_count AND json_extract(NEW.result_json,'$.counts.unmintedReserve') IS 1000-json_extract(c.state,'$.fulfilled') AND json_extract(NEW.result_json,'$.stages') IS json_extract(NEW.prefix_json,'$.stages') AND json_extract(NEW.result_json,'$.historicalEconomics') IS 1 AND json_extract(NEW.result_json,'$.originalOperatorAuthentication') IS 0 AND json_extract(NEW.result_json,'$.paymentVerified') IS 0 AND json_extract(NEW.result_json,'$.adoptionAuthorized') IS 0 AND json_extract(NEW.result_json,'$.executable') IS 0);
END;
CREATE TRIGGER collection_legacy_economics_no_delete BEFORE DELETE ON app_collection_legacy_economics BEGIN SELECT RAISE(ABORT,'Retain private economic history'); END;
CREATE TRIGGER collection_legacy_economic_stages_no_update BEFORE UPDATE ON app_collection_legacy_economic_stages BEGIN SELECT RAISE(ABORT,'Retain private stage proof'); END;
CREATE TRIGGER collection_legacy_economic_stages_no_delete BEFORE DELETE ON app_collection_legacy_economic_stages BEGIN SELECT RAISE(ABORT,'Retain private stage proof'); END;
CREATE TRIGGER collection_legacy_economic_phases_no_update BEFORE UPDATE ON app_collection_legacy_economic_phases BEGIN SELECT RAISE(ABORT,'Retain private phase proof'); END;
CREATE TRIGGER collection_legacy_economic_phases_no_delete BEFORE DELETE ON app_collection_legacy_economic_phases BEGIN SELECT RAISE(ABORT,'Retain private phase proof'); END;
